func ptrEvalCase(p unsafe.Pointer, c int32) any {
	r := (*agentquality.EvalCase)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.AgentDefinitionID))
	case 4:
		return &r.Title
	case 5:
		return (*string)(unsafe.Pointer(&r.Source))
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return &r.Automatic
	case 8:
		return (*string)(unsafe.Pointer(&r.Trigger))
	case 9:
		return (**string)(unsafe.Pointer(&r.SourceRunID))
	case 10:
		return (**string)(unsafe.Pointer(&r.SourceTurnID))
	case 11:
		return (**string)(unsafe.Pointer(&r.SourceThreadID))
	case 12:
		return (**string)(unsafe.Pointer(&r.SourceMessageID))
	case 13:
		return (**string)(unsafe.Pointer(&r.SourceProposalID))
	case 14:
		return (**string)(unsafe.Pointer(&r.SourceFeedbackID))
	case 15:
		return &r.Input
	case 16:
		return &r.AskedAt
	case 17:
		return &r.History
	case 18:
		return &r.PageContext
	case 19:
		return &r.Mentions
	case 20:
		return (*string)(unsafe.Pointer(&r.SubjectType))
	case 21:
		return (*string)(unsafe.Pointer(&r.SubjectID))
	case 22:
		return &r.HeldTools
	case 23:
		return &r.ToolFixtures
	case 24:
		return &r.Expected
	case 25:
		return &r.Rubric
	case 26:
		return &r.Redaction
	case 27:
		return &r.ContentHash
	case 28:
		return &r.CapturedFingerprint
	case 29:
		return &r.ExpiresAt
	case 30:
		return (**string)(unsafe.Pointer(&r.CreatedByUserID))
	case 31:
		return &r.Version
	case 32:
		return &r.CreatedAt
	case 33:
		return &r.UpdatedAt
	}
	return nil
}

func valueEvalCase(p unsafe.Pointer, c int32) any {
	r := (*agentquality.EvalCase)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.AgentDefinitionID)
	case 4:
		if r.Title == "" {
			return nil
		}
		return r.Title
	case 5:
		return string(r.Source)
	case 6:
		return string(r.Status)
	case 7:
		return r.Automatic
	case 8:
		return string(r.Trigger)
	case 9:
		if r.SourceRunID == nil {
			return nil
		}
		return string(*r.SourceRunID)
	case 10:
		if r.SourceTurnID == nil {
			return nil
		}
		return string(*r.SourceTurnID)
	case 11:
		if r.SourceThreadID == nil {
			return nil
		}
		return string(*r.SourceThreadID)
	case 12:
		if r.SourceMessageID == nil {
			return nil
		}
		return string(*r.SourceMessageID)
	case 13:
		if r.SourceProposalID == nil {
			return nil
		}
		return string(*r.SourceProposalID)
	case 14:
		if r.SourceFeedbackID == nil {
			return nil
		}
		return string(*r.SourceFeedbackID)
	case 15:
		return r.Input
	case 16:
		if r.AskedAt == nil {
			return nil
		}
		return *r.AskedAt
	case 17:
		if r.History == nil {
			return keel.EmptyJSONArray
		}
		return r.History
	case 18:
		if r.PageContext == nil {
			return nil
		}
		return *r.PageContext
	case 19:
		if r.Mentions == nil {
			return keel.EmptyJSONArray
		}
		return r.Mentions
	case 20:
		if r.SubjectType == "" {
			return nil
		}
		return string(r.SubjectType)
	case 21:
		if r.SubjectID == "" {
			return nil
		}
		return string(r.SubjectID)
	case 22:
		if r.HeldTools == nil {
			return []string{}
		}
		return r.HeldTools
	case 23:
		if r.ToolFixtures == nil {
			return keel.EmptyJSONArray
		}
		return r.ToolFixtures
	case 24:
		return r.Expected
	case 25:
		if r.Rubric == "" {
			return nil
		}
		return r.Rubric
	case 26:
		if r.Redaction == nil {
			return nil
		}
		return *r.Redaction
	case 27:
		return r.ContentHash
	case 28:
		if r.CapturedFingerprint == nil {
			return nil
		}
		return *r.CapturedFingerprint
	case 29:
		if r.ExpiresAt == nil {
			return nil
		}
		return *r.ExpiresAt
	case 30:
		if r.CreatedByUserID == nil {
			return nil
		}
		return string(*r.CreatedByUserID)
	case 31:
		return r.Version
	case 32:
		return r.CreatedAt
	case 33:
		return r.UpdatedAt
	}
	return nil
}

